import re


def rule_argued_or_submitted_date(doc: dict) -> list[dict]:
    try:
        def _intish(value, default):
            try:
                if value is None:
                    return default
                return int(value)
            except Exception:
                return default

        month_pat = (
            r"(?:January|February|March|April|May|June|July|August|"
            r"September|October|November|December)"
        )
        date_pat = month_pat + r"\s+\d{1,2},\s+\d{4}"
        header_pat = re.compile(
            r"^\s*((?:Argued(?:\s+and)?\s+Submitted|Argued|Submitted)"
            r"(?:\s+En Banc)?\s+" + date_pat + r")\b",
            re.IGNORECASE,
        )
        oral_pat = re.compile(
            r"(\bheard\s+oral\s+argument\b.*?\bon\s+" + date_pat + r")\b",
            re.IGNORECASE | re.DOTALL,
        )
        header_any_pat = re.compile(
            r"(?:^|\n)\s*((?:Argued(?:\s+and)?\s+Submitted|Argued|Submitted)"
            r"(?:\s+En Banc)?\s+" + date_pat + r")\b",
            re.IGNORECASE,
        )
        oral_any_pat = re.compile(
            r"(\bheard\s+oral\s+argument\b.*?\bon\s+" + date_pat + r")\b",
            re.IGNORECASE | re.DOTALL,
        )

        lines = doc.get("lines") or []
        ordered = sorted(
            lines,
            key=lambda x: (
                _intish(x.get("page_no"), 10**9),
                _intish(x.get("line_no"), 10**9),
            ),
        )

        for item in ordered[:120]:
            text = (item.get("text") or "").replace("\x0c", " ").strip()
            if not text:
                continue

            m = header_pat.search(text)
            if m:
                return [
                    {
                        "text": m.group(1).strip(),
                        "page_no": item.get("page_no"),
                        "line_no": item.get("line_no"),
                    }
                ]

            if "oral argument" in text.lower():
                m = oral_pat.search(text)
                if m:
                    return [
                        {
                            "text": m.group(1).strip(),
                            "page_no": item.get("page_no"),
                            "line_no": item.get("line_no"),
                        }
                    ]

        paragraphs = doc.get("paragraphs") or []
        ordered_paragraphs = sorted(
            paragraphs,
            key=lambda x: (
                _intish(x.get("page_no"), 10**9),
                _intish(x.get("paragraph_no"), 10**9),
            ),
        )

        for item in ordered_paragraphs[:40]:
            text = (item.get("text") or "").replace("\x0c", " ").strip()
            if not text:
                continue

            m = header_pat.search(text)
            if m:
                result = {"text": m.group(1).strip()}
                if item.get("page_no") is not None:
                    result["page_no"] = item.get("page_no")
                if item.get("paragraph_no") is not None:
                    result["paragraph_no"] = item.get("paragraph_no")
                return [result]

            m = oral_pat.search(text)
            if m:
                result = {"text": m.group(1).strip()}
                if item.get("page_no") is not None:
                    result["page_no"] = item.get("page_no")
                if item.get("paragraph_no") is not None:
                    result["paragraph_no"] = item.get("paragraph_no")
                return [result]

        full_text = (doc.get("text") or "").replace("\x0c", " ")
        for blob in (
            full_text[:8000],
            "\n".join((p.get("text") or "").replace("\x0c", " ") for p in (doc.get("pages") or [])[:2]),
        ):
            if not blob:
                continue

            m = header_any_pat.search(blob)
            if m:
                return [{"text": m.group(1).strip()}]

            m = oral_any_pat.search(blob)
            if m:
                return [{"text": m.group(1).strip()}]

        return []
    except Exception:
        return []

from __future__ import annotations
import re


_ARGUED_AND_SUBMITTED_RE = re.compile(
    r"(?i)^\s*Argued and Submitted(?:\s+En Banc)?\s+"
    r"(?P<date>[A-Z][a-z]+ \d{1,2}, \d{4})(?:\s*\*+\s*)?\s*$"
)
_SUBMITTED_RE = re.compile(
    r"(?i)^\s*Submitted(?:\s+on the briefs)?(?:\s+En Banc)?\s+"
    r"(?P<date>[A-Z][a-z]+ \d{1,2}, \d{4})(?:\s*\*+\s*)?\s*$"
)


def rule_argument_submission_date_header(doc: dict) -> list[dict]:
    try:
        spans = []
        seen = set()

        def add_span(span_text: str, source_item: dict) -> None:
            cleaned = re.sub(r"\s+", " ", (span_text or "")).strip().rstrip(".,;:")
            if not cleaned:
                return
            key = cleaned.lower()
            if key in seen:
                return
            seen.add(key)
            span = {"text": cleaned}
            for field in ("page_no", "line_no", "paragraph_no"):
                if field in source_item:
                    span[field] = source_item[field]
            spans.append(span)

        def extract_date(text: str) -> str | None:
            normalized = re.sub(r"\s+", " ", (text or "")).strip()
            if not normalized:
                return None
            for pattern in (_ARGUED_AND_SUBMITTED_RE, _SUBMITTED_RE):
                match = pattern.match(normalized)
                if match:
                    return match.group("date")
            return None

        def scan_items(items: list[dict]) -> None:
            limit = min(len(items or []), 80)
            for i in range(limit):
                item = items[i] or {}
                text = (item.get("text") or "").strip()
                if not text:
                    continue

                if extract_date(text):
                    add_span(text, item)
                    return

                # Some OCR variants split the header across adjacent rows.
                if i + 1 < limit:
                    next_item = items[i + 1] or {}
                    next_text = (next_item.get("text") or "").strip()
                    if next_text:
                        combined = f"{text} {next_text}"
                        if extract_date(combined):
                            add_span(combined, item)
                            return

        scan_items(doc.get("lines") or [])
        if not spans:
            scan_items(doc.get("paragraphs") or [])

        if not spans:
            full_text = doc.get("text") or ""
            for pattern in (_ARGUED_AND_SUBMITTED_RE, _SUBMITTED_RE):
                match = pattern.search(full_text)
                if match:
                    add_span(match.group(0), {})
                    break

        return spans
    except Exception:
        return []

def rule_city_after_argued_submitted_header(doc: dict) -> list[dict]:
    try:
        import re

        lines = doc.get("lines") or []
        if not isinstance(lines, list):
            return []

        lines = sorted(
            [line for line in lines if isinstance(line, dict)],
            key=lambda x: (x.get("page_no", 0), x.get("line_no", 0)),
        )

        header_re = re.compile(r"\b(argued|submitted|resubmitted)\b", re.I)
        city_re = re.compile(
            r"^[A-Z][A-Za-z0-9'.-]*(?: [A-Z][A-Za-z0-9'.-]*)*, [A-Z][A-Za-z .'-]{2,}$"
        )

        def norm_text(x):
            return (x or "").strip()

        for idx, line in enumerate(lines[:120]):
            text = norm_text(line.get("text"))
            if not text or not header_re.search(text):
                continue
            if not re.search(r"\b\d{4}\b", text):
                continue
            for nxt in lines[idx + 1 : idx + 5]:
                nxt_text = norm_text(nxt.get("text"))
                if not nxt_text:
                    continue
                if city_re.match(nxt_text):
                    out = {"text": nxt_text}
                    if "page_no" in nxt:
                        out["page_no"] = nxt.get("page_no")
                    if "line_no" in nxt:
                        out["line_no"] = nxt.get("line_no")
                    return [out]
                if "Filed" in nxt_text or "Before:" in nxt_text:
                    break
        return []
    except Exception:
        return []

def rule_city_from_oral_argument_order_phrase(doc: dict) -> list[dict]:
    try:
        import re

        lines = doc.get("lines") or []
        if not isinstance(lines, list):
            return []

        lines = sorted(
            [line for line in lines if isinstance(line, dict)],
            key=lambda x: (x.get("page_no", 0), x.get("line_no", 0)),
        )

        trigger_re = re.compile(
            r"(reschedule oral argument|oral argument to the week|submission for this case is vacated|submission is vacated)",
            re.I,
        )
        city_line_re = re.compile(
            r"^[A-Z][A-Za-z0-9'.-]*(?: [A-Z][A-Za-z0-9'.-]*)*, [A-Z][A-Za-z .'-]{2,}$"
        )

        def clean(text: str) -> str:
            return (text or "").strip().rstrip(" .;:")

        for idx, line in enumerate(lines[:80]):
            window = [clean(line.get("text", ""))]
            for nxt in lines[idx + 1 : idx + 3]:
                window.append(clean(nxt.get("text", "")))
            text = " ".join(part for part in window if part)
            if not text or not trigger_re.search(text):
                continue
            m = re.search(r"\bin\s+([A-Z][^.;:\n]+)", text)
            if m:
                city_text = clean(m.group(1))
                if not city_line_re.match(city_text):
                    continue
                out = {"text": city_text}
                if "page_no" in line:
                    out["page_no"] = line.get("page_no")
                if "line_no" in line:
                    out["line_no"] = line.get("line_no")
                return [out]
            for nxt in lines[idx + 1 : idx + 4]:
                nxt_text = clean(nxt.get("text", ""))
                if city_line_re.match(nxt_text):
                    out = {"text": nxt_text}
                    if "page_no" in nxt:
                        out["page_no"] = nxt.get("page_no")
                    if "line_no" in nxt:
                        out["line_no"] = nxt.get("line_no")
                    return [out]
        return []
    except Exception:
        return []

