  "code": "import re\n\n\ndef rule_argued_or_submitted_date_header(doc: dict) -> list[dict]:\n    try:\n        month_pat = (\n            r\"(?:January|February|March|April|May|June|July|August|\"\n            r\"September|October|November|December)\"\n        )\n        date_pat = rf\"{month_pat}\\s+\\d{{1,2}},\\s+\\d{{4}}\"\n        header_patterns = (\n            re.compile(\n                rf\"^\\s*(Argued\\s+and\\s+Submitted(?:\\s+En\\s+Banc)?\\s+{date_pat}(?:\\s*\\*+)?)\\s*$\",\n                re.IGNORECASE,\n            ),\n            re.compile(\n                rf\"^\\s*(Submitted(?:\\s+on\\s+the\\s+briefs)?(?:\\s+En\\s+Banc)?\\s+{date_pat}(?:\\s*\\*+)?)\\s*$\",\n                re.IGNORECASE,\n            ),\n            re.compile(\n                rf\"^\\s*(Argued(?:\\s+En\\s+Banc)?\\s+{date_pat}(?:\\s*\\*+)?)\\s*$\",\n                re.IGNORECASE,\n            ),\n        )\n        negative_prefixes = (\n            \"submission deferred\",\n            \"submission vacated\",\n            \"submission withdrawn\",\n            \"resubmitted\",\n        )\n\n        def _intish(value, default):\n            try:\n                return int(value)\n            except Exception:\n                return default\n\n        def _clean(text: str) -> str:\n            return re.sub(r\"\\s+\", \" \", (text or \"\").replace(\"\\x0c\", \" \")).strip()\n\n        def _extract(text: str) -> str | None:\n            cleaned = _clean(text)\n            if not cleaned:\n                return None\n            lowered = cleaned.lower()\n            if lowered.startswith(negative_prefixes):\n                return None\n            for pattern in header_patterns:\n                match = pattern.match(cleaned)\n                if match:\n                    return match.group(1).strip()\n            return None\n\n        def _scan_items(items: list[dict], line_field: str) -> list[dict]:\n            ordered = sorted(\n                [item for item in (items or